import React, { useState } from 'react';
import Navbar from './components/Navbar';
import Card from './components/Card';
import Cart from './pages/Cart';
import Home from './pages/Home';
import Orders from './pages/Orders';
import Footer from './components/Footer'; 

const MOCK_PRODUCTS = [
  { id: 1, name: "Wireless Noise-Canceling Headphones", price: 12499, category: "Electronics", tag: "best-seller" },
  { id: 2, name: "Minimalist Leather Quartz Watch", price: 6999, category: "Electronics", tag: "trending" },
  { id: 3, name: "Mechanical RGB Gaming Keyboard", price: 4200, category: "Electronics", tag: "best-seller" },
  { id: 4, name: "Ergonomic Bluetooth Wireless Mouse", price: 1899, category: "Electronics", tag: "normal" },
  { id: 5, name: "Ultra-Wide 2K Curved Monitor", price: 24999, category: "Electronics", tag: "trending" },
  { id: 6, name: "Portable Waterproof Bass Speaker", price: 3499, category: "Electronics", tag: "normal" },
  { id: 7, name: "Vintage Oversized Corduroy Jacket", price: 4500, category: "Clothing", tag: "trending" },
  { id: 8, name: "Classic Cotton Crewneck Sweatshirt", price: 2499, category: "Clothing", tag: "normal" },
  { id: 9, name: "Slim Fit Stretch Denim Jeans", price: 3200, category: "Clothing", tag: "best-seller" },
  { id: 10, name: "Breathable Knit Running Sneakers", price: 5800, category: "Clothing", tag: "trending" },
  { id: 11, name: "Pack of 3 Premium Solid Cotton Tees", price: 1499, category: "Clothing", tag: "best-seller" },
  { id: 12, name: "Water-Resistant Daily Windbreaker", price: 3999, category: "Clothing", tag: "normal" },
  { id: 13, name: "The Art of Clean Code (Hardcover)", price: 1199, category: "Books", tag: "best-seller" },
  { id: 14, name: "Designing Systems for Scale", price: 1850, category: "Books", tag: "trending" },
  { id: 15, name: "Introduction to Algorithm Architecture", price: 2400, category: "Books", tag: "normal" },
  { id: 16, name: "The Pragmatic Thinker's Handbook", price: 999, category: "Books", tag: "best-seller" },
  { id: 17, name: "Building Creative User Interfaces", price: 1450, category: "Books", tag: "normal" }
];

const CATEGORIES = [
  { name: "Electronics", image: "data:image/avif;base64," },
  { name: "Clothing", image: "data:image/avif;base64," },
  { name: "Books", image: "data:image/avif;base64,"}
];

export default function App() {
  const [currentView, setCurrentView] = useState("home");
  const [cartItems, setCartItems] = useState([]);
  const [orders, setOrders] = useState([]);

  const handleAddToCart = (product) => {
    setCartItems((prevItems) => {
      const existingItem = prevItems.find(item => item.id === product.id);
      if (existingItem) {
        return prevItems.map(item =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prevItems, { ...product, quantity: 1 }];
    });
  };

  const handleUpdateQuantity = (id, change) => {
    setCartItems((prevItems) =>
      prevItems
        .map((item) =>
          item.id === id ? { ...item, quantity: item.quantity + change } : item
        )
        .filter((item) => item.quantity > 0)
    );
  };

  const handleCheckout = () => {
    const newOrder = {
      items: [...cartItems],
      total: totalBillAmount
    };
    setOrders([newOrder, ...orders]);
    setCartItems([]);
    setCurrentView("orders");
  };

  const totalCartCount = cartItems.reduce((total, item) => total + item.quantity, 0);
  const totalBillAmount = cartItems.reduce((total, item) => total + (item.price * item.quantity), 0);

  const filteredProducts = MOCK_PRODUCTS.filter(
    product => product.category === currentView
  );

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col justify-between">
      
      <div>
        <Navbar 
          cartCount={totalCartCount} 
          onLogoClick={() => setCurrentView("home")} 
          onCartClick={() => setCurrentView("cart")}
        />
        
        <main className="max-w-7xl mx-auto p-6">
          {currentView === "home" && (
            <Home 
              categories={CATEGORIES} 
              allProducts={MOCK_PRODUCTS}
              onSelectCategory={(cat) => setCurrentView(cat)} 
              onAddToCart={handleAddToCart}
            />
          )}

          {currentView !== "home" && currentView !== "cart" && currentView !== "orders" && (
            <div>
              <div className="flex items-center justify-between mb-6">
                <button 
                  onClick={() => setCurrentView("home")}
                  className="text-sm font-semibold text-[#BA6FA9] hover:underline"
                >
                  ← Back to Categories
                </button>
                <h2 className="text-2xl font-black text-gray-800">{currentView}</h2>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredProducts.map((product) => (
                  <Card 
                    key={product.id}
                    name={product.name}
                    price={product.price}
                    onAddToCart={() => handleAddToCart(product)}
                  />
                ))}
              </div>
            </div>
          )}

          {currentView === "cart" && (
            <Cart 
              cartItems={cartItems}
              totalBillAmount={totalBillAmount}
              onNavigateHome={() => setCurrentView("home")}
              onUpdateQuantity={handleUpdateQuantity}
              onCheckout={handleCheckout}
            />
          )}

          {currentView === "orders" && (
            <Orders 
              orders={orders} 
              onNavigateHome={() => setCurrentView("home")} 
            />
          )}
        </main>
      </div>

      <Footer />
      
    </div>
  );
}
